// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-button-group.js';
import '../button/md-gb-button.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** The index of the item that holds focus (also inside its shadow root), or -1. */
function focusedIndex(items: Element[]) {
  const path: Element[] = [];
  let el = document.activeElement;
  while (el) {
    path.push(el);
    el = el.shadowRoot?.activeElement ?? null;
  }
  return items.findIndex((item) => path.some((e) => e === item || item.contains(e)));
}

/** Focuses item `index` (negative counts from the end). */
async function focusItem(f: {items: HTMLElement[]}, index: number) {
  f.items[(index + f.items.length) % f.items.length].focus();
  await settle();
}

async function setup(opts: {dir?: string; disabled?: number} = {}) {
  const root = await mount(html`
    <button id="before">Before</button>
    <div dir=${opts.dir ?? 'ltr'}>
      <md-gb-button-group aria-label="Text formatting">
      <md-gb-button>Alpha</md-gb-button>
      <md-gb-button>Bravo</md-gb-button>
      <md-gb-button>Charlie</md-gb-button>
      <md-gb-button>Delta</md-gb-button>
      </md-gb-button-group>
    </div>
    <button id="after">After</button>
  `);
  const items = [...root.querySelectorAll<HTMLElement>('md-gb-button')];
  if (opts.disabled !== undefined) {
    items[opts.disabled].setAttribute('disabled', '');
    await settle();
  }
  return {
    group: root.querySelector<HTMLElement>('md-gb-button-group')!,
    items,
    before: root.querySelector<HTMLElement>('#before')!,
    after: root.querySelector<HTMLElement>('#after')!,
  };
}

describe('<md-gb-button-group> roving focus contract (RovingFocusController: horizontal, wrap, no Home/End, every item tabbable)', () => {
  afterEach(() => container?.remove());

  it('is entered with Tab on the first item; the container takes no focus', async () => {
    // spec: button-groups-5e4950, button-groups-ebecb4, button-groups-ceae8c, button-groups-1c8984, button-groups-257fef
    const f = await setup();
    f.before.focus();
    await press('Tab');
    expect(focusedIndex(f.items)).toBe(0);
    expect(f.group.matches(':focus')).toBeFalse();
  });

  it('moves focus to the next and previous item with ArrowRight / ArrowLeft', async () => {
    // spec: button-groups-257fef, button-groups-9760fc, button-groups/accessibility/keyboard-navigation
    const f = await setup();
    await focusItem(f, 1);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(2);
    await press('ArrowLeft');
    await press('ArrowLeft');
    expect(focusedIndex(f.items)).toBe(0);
  });

  it('does not move focus with ArrowDown (horizontal only)', async () => {
    // spec: button-groups-257fef, button-groups-9760fc, button-groups/accessibility/keyboard-navigation
    const f = await setup();
    await focusItem(f, 1);
    await press('ArrowDown');
    expect(focusedIndex(f.items)).toBe(1);
  });

  it('wraps from the last item to the first and back', async () => {
    // spec: button-groups-257fef, button-groups-9760fc, button-groups/accessibility/keyboard-navigation
    const f = await setup();
    await focusItem(f, -1);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(0);
    await press('ArrowLeft');
    expect(focusedIndex(f.items)).toBe(f.items.length - 1);
  });

  it('mirrors Left and Right in right-to-left layouts, and Tab still enters on the first item', async () => {
    const f = await setup({dir: 'rtl'});
    f.before.focus();
    await press('Tab');
    expect(focusedIndex(f.items)).toBe(0);
    await press('ArrowLeft');
    expect(focusedIndex(f.items)).toBe(1);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(0);
  });

  it('does not move focus with Home and End', async () => {
    const f = await setup();
    await focusItem(f, 1);
    await press('End');
    expect(focusedIndex(f.items)).toBe(1);
  });

  it('skips disabled items', async () => {
    const f = await setup({disabled: 1});
    await focusItem(f, 0);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(2);
  });

  it('keeps every item in the tab order', async () => {
    // spec: button-groups-ebecb4
    const f = await setup();
    await focusItem(f, 0);
    await press('Tab');
    expect(focusedIndex(f.items)).toBe(1);
  });
});


const SELECTION_LABELS = ["Alpha","Bravo","Charlie","Delta"];
const SELECTION_MODE_ATTRS: {[mode: string]: string} = {"single":"selection=\"single\"","multiple":"selection=\"multiple\"","none":"selection=\"none\""};

interface SelectionFixture {
  form: HTMLFormElement;
  group: HTMLElement;
  items: HTMLElement[];
}

async function setupSelection(opts: {
  mode: string;
  required?: boolean;
  disabled?: number;
  name?: boolean;
}): Promise<SelectionFixture> {
  const root = await mount(html``);
  const attrs = [
    SELECTION_MODE_ATTRS[opts.mode],
    opts.required ? 'required' : '',
    opts.name ? 'name=""' : '',
  ]
    .filter(Boolean)
    .map((attr) => ' ' + attr)
    .join('');
  const item = (label: string, extra: string) => `<md-gb-button value="${label}"${extra}>${label}</md-gb-button>`;
  const items = SELECTION_LABELS.map((label, i) => item(label, opts.disabled === i ? ' disabled' : '')).join('');
  root.innerHTML = `<form><md-gb-button-group aria-label="Text formatting"${attrs}>${items}</md-gb-button-group></form>`;
  await settle();
  const f = {
    form: root.querySelector('form')!,
    group: root.querySelector<HTMLElement>('md-gb-button-group')!,
    items: [...root.querySelectorAll<HTMLElement>('md-gb-button')],
  };
  await settle();
  return f;
}

/** The labels of the selected items, in order. */
function selectedLabels(f: SelectionFixture) {
  return f.items.filter((item) => (item as HTMLElement & {selected: boolean}).selected).map((item) => item.textContent!.trim());
}

/** The ARIA state of each item. */
function ariaStates(f: SelectionFixture) {
  return f.items.map((item) => item.shadowRoot!.querySelector('[part="btn"]')?.getAttribute('aria-pressed') ?? null);
}

/** The event types the group dispatches, in order. */
function recordSelectionEvents(group: HTMLElement) {
  const log: string[] = [];
  for (const type of ['input', 'change']) group.addEventListener(type, () => log.push(type));
  return log;
}


describe('<md-gb-button-group> selection contract (SelectionController: none, single, multiple, required)', () => {
  afterEach(() => container?.remove());

  it('selects the clicked item and unselects the previous one (single-select)', async () => {
    // spec: button-groups-44ca7f, button-groups-8b0224
    const f = await setupSelection({mode: 'single'});
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Bravo']);
    f.items[2].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Charlie']);
  });

  it('selects the focused item with Space and with Enter', async () => {
    // spec: button-groups-257fef, button-groups-d2318f, button-groups-2138f9, button-groups-03dfe3
    const f = await setupSelection({mode: 'single'});
    await focusItem(f, 1);
    await press('Space');
    expect(selectedLabels(f)).toEqual(['Bravo']);
    await focusItem(f, 2);
    await press('Enter');
    expect(selectedLabels(f)).toEqual(['Charlie']);
  });

  it('toggles items independently in multi-select', async () => {
    // spec: button-groups-44ca7f, button-groups-8b0224
    const f = await setupSelection({mode: 'multiple'});
    f.items[0].click();
    f.items[2].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Alpha', 'Charlie']);
    f.items[0].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Charlie']);
  });

  it('selects and unselects the focused item with Space and Enter (multi-select)', async () => {
    // spec: button-groups-44ca7f, button-groups-8b0224
    const f = await setupSelection({mode: 'multiple'});
    await focusItem(f, 0);
    await press('Space');
    await focusItem(f, 1);
    await press('Enter');
    expect(selectedLabels(f)).toEqual(['Alpha', 'Bravo']);
    await focusItem(f, 0);
    await press('Space');
    expect(selectedLabels(f)).toEqual(['Bravo']);
    await focusItem(f, 1);
    await press('Enter');
    expect(selectedLabels(f)).toEqual([]);
  });

  it('lets every item be selected, or none, in multi-select even when required', async () => {
    // spec: button-groups-44ca7f, button-groups-8b0224
    const f = await setupSelection({mode: 'multiple', required: true});
    for (const item of f.items) item.click();
    await settle();
    expect(selectedLabels(f)).toEqual(SELECTION_LABELS);
    for (const item of f.items) item.click();
    await settle();
    expect(selectedLabels(f)).toEqual([]);
  });

  it('selects nothing and fires no events in none mode', async () => {
    const f = await setupSelection({mode: 'none'});
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await focusItem(f, 2);
    await press('Space');
    expect(selectedLabels(f)).toEqual([]);
    expect(log).toEqual([]);
  });

  it('keeps the selected item selected when required, but still switches', async () => {
    // spec: button-groups-8b0224
    const f = await setupSelection({mode: 'single', required: true});
    f.items[1].click();
    await settle();
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Bravo']);
    await focusItem(f, 1);
    await press('Space');
    await press('Enter');
    expect(selectedLabels(f)).toEqual(['Bravo']);
    f.items[3].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Delta']);
  });

  it('unselects the selected item when it is activated again (not required)', async () => {
    const f = await setupSelection({mode: 'single'});
    f.items[1].click();
    await settle();
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual([]);
    await focusItem(f, 2);
    await press('Space');
    expect(selectedLabels(f)).toEqual(['Charlie']);
    await press('Enter');
    expect(selectedLabels(f)).toEqual([]);
  });

  it('reflects the selection as aria-pressed on each item', async () => {
    // spec: button-groups-a9d07e
    const f = await setupSelection({mode: 'single'});
    expect(ariaStates(f)).toEqual(['false', 'false', 'false', 'false']);
    f.items[1].click();
    await settle();
    expect(ariaStates(f)).toEqual(['false', 'true', 'false', 'false']);
    f.items[1].click();
    await settle();
    expect(ariaStates(f)).toEqual(['false', 'false', 'false', 'false']);
  });

  it('reflects every selected item as aria-pressed in multi-select', async () => {
    // spec: button-groups-a9d07e
    const f = await setupSelection({mode: 'multiple'});
    f.items[0].click();
    f.items[2].click();
    await settle();
    expect(ariaStates(f)).toEqual(['true', 'false', 'true', 'false']);
  });

  it('has no aria-pressed state in none mode (the buttons only act)', async () => {
    // spec: button-groups-a9d07e
    const f = await setupSelection({mode: 'none'});
    expect(ariaStates(f)).toEqual([null, null, null, null]);
  });

  it('fires input then change on the group when the user selects, by click and by key', async () => {
    const f = await setupSelection({mode: 'single'});
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(log).toEqual(['input', 'change']);
    log.length = 0;
    await focusItem(f, 2);
    await press('Space');
    expect(log).toEqual(['input', 'change']);
  });

  it('fires no events when the selection is changed programmatically', async () => {
    const f = await setupSelection({mode: 'single'});
    const log = recordSelectionEvents(f.group);
    (f.items[2] as HTMLElement & {selected: boolean}).selected = true;
    await settle();
    expect(selectedLabels(f)).toContain('Charlie');
    expect(log).toEqual([]);
  });

  it('fires no events when nothing changes (the selected item of a required group)', async () => {
    const f = await setupSelection({mode: 'single', required: true});
    f.items[1].click();
    await settle();
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(log).toEqual([]);
  });

  it('does not select a disabled item', async () => {
    const f = await setupSelection({mode: 'single', disabled: 1});
    const before = selectedLabels(f);
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(before);
    expect(log).toEqual([]);
  });
});
